      change_kind    text        NOT NULL,
      changed_fields text[]      NOT NULL,
      before         jsonb       NULL,
      after          jsonb       NOT NULL,
      row_version    bigint      NOT NULL,
      CONSTRAINT location_login_config_change_pkey PRIMARY KEY (change_id),
