    CREATE TABLE auth.oidc_replay (
      kind       text        NOT NULL,
      key_hash   bytea       NOT NULL,
      created_at timestamptz NOT NULL DEFAULT now(),
      expires_at timestamptz NOT NULL,
      CONSTRAINT oidc_replay_pkey PRIMARY KEY (kind, key_hash),
